             `).join('')}
           </div>
         </div>
       `).join('') || '<div style="color:var(--t3);font-size:12px">Релизов нет</div>';
     } else {
       list.innerHTML = '<div style="color:var(--t3);font-size:12px">Релизов нет</div>';
