     .term-scroll-handle:active{cursor:grabbing}
     .term-scroll-track{display:none}
     .term-cd{display:none;position:absolute;right:12px;bottom:8px;background:rgba(210,153,34,.14);border:1px solid var(--warn);color:var(--warn);border-radius:8px;font-size:11px;font-weight:700;font-family:monospace;padding:3px 9px;z-index:6;pointer-events:none;white-space:nowrap}
     .term-cd.on{display:block}

     /* File manager */
     .fm-item{display:flex;align-items:center;gap:8px;padding:7px 12px;cursor:pointer;border-bottom:1px solid var(--bdr);transition:background .08s}
     .fm-item:hover{background:var(--bg3)}.fm-item.fm-sel{background:rgba(88,166,255,.1)}
     .fm-ico{font-size:16px;flex-shrink:0;width:22px;text-align:center}
     .fm-name{flex:1;font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
     .fm-size{font-size:10px;color:var(--t3);flex-shrink:0;min-width:60px;text-align:right}

     /* Path picker dropdown */
     .path-picker{position:relative}
     .path-dropdown{display:none;position:absolute;top:100%;left:0;right:0;background:var(--bg2);border:1px solid var(--bdr);border-radius:6px;max-height:200px;overflow-y:auto;z-index:50;margin-top:2px}
