     .path-dd-item:hover{background:var(--bg3);color:var(--t1)}

     /* Modal */
     .modal-bg{display:none;position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:100;align-items:center;justify-content:center}
     .modal-bg.on{display:flex}
     .modal{background:var(--bg2);border:1px solid var(--bdr);border-radius:12px;padding:20px;width:560px;max-width:90vw;max-height:80vh;display:flex;flex-direction:column}
     .modal h2{font-size:16px;font-weight:600;margin-bottom:12px}
     .modal-bar{display:flex;gap:6px;margin-bottom:10px}
     .modal-bar input{flex:1;padding:7px 10px;background:var(--bg0);border:1px solid var(--bdr);border-radius:6px;color:var(--t1);font-size:12px;font-family:monospace;outline:none}
     .modal-bar input:focus{border-color:var(--acc)}
     .modal-drives{display:flex;gap:4px;margin-bottom:10px;flex-wrap:wrap}
     .drive-btn{padding:5px 10px;background:var(--bg3);border:1px solid var(--bdr);border-radius:6px;color:var(--t2);font-size:11px;cursor:pointer;transition:all .1s}
     .drive-btn:hover{border-color:var(--acc);color:var(--t1)}
     .git-pre{background:var(--bg0);border:1px solid var(--bdr);border-radius:8px;padding:12px;overflow:auto;max-height:380px;font-size:11px;line-height:1.5;white-space:pre-wrap;word-break:break-all}
     .git-file{display:flex;gap:8px;align-items:baseline;padding:3px 0;font-size:12px;font-family:monospace}
     .git-code{color:var(--warn);width:18px;flex-shrink:0}
     .modal-list{flex:1;overflow-y:auto;max-height:300px;border:1px solid var(--bdr);border-radius:6px;background:var(--bg0)}
     .modal-actions{display:flex;gap:6px;margin-top:12px;justify-content:flex-end}
     .newterm-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:14px}
     .newterm-tool{display:flex;align-items:center;gap:8px;padding:10px;background:var(--bg3);border:1px solid var(--bdr);border-radius:8px;cursor:pointer;transition:all .12s}
     .newterm-tool:hover{border-color:var(--acc)}.newterm-tool.off{opacity:.35;pointer-events:none}
     .storage-type-btn{padding:5px 10px;background:var(--bg3);border:1px solid var(--bdr);border-radius:6px;color:var(--t2);font-size:11px;cursor:pointer;transition:all .1s}
     .storage-type-btn:hover{border-color:var(--acc);color:var(--t1)}.storage-type-btn.on{border-color:var(--acc);color:var(--acc);background:rgba(88,166,255,.1)}
     .model-card{background:var(--bg3);border:1px solid var(--bdr);border-radius:10px;padding:14px;transition:all .15s}
     .model-card:hover{border-color:var(--acc)}
     .model-card.selected{border-color:var(--ok);background:rgba(63,185,80,.05)}
     .model-card .model-name{font-size:13px;font-weight:600;margin-bottom:4px}
     .model-card .model-id{font-size:9px;color:var(--t3);font-family:monospace;word-break:break-all}
     .model-card .model-tools{display:flex;gap:4px;margin-top:8px;flex-wrap:wrap}
     .model-card .model-tool{font-size:8px;padding:2px 6px;border-radius:4px;background:var(--bg4);color:var(--t2)}
     .tool-config-card{background:var(--bg3);border:1px solid var(--bdr);border-radius:10px;padding:14px}
     .tool-config-card .tc-name{font-size:13px;font-weight:600;margin-bottom:6px}
     .tool-config-card .tc-key{font-size:9px;color:var(--t3);font-family:monospace;word-break:break-all;margin-top:4px}

     ::-webkit-scrollbar{width:6px;height:6px}::-webkit-scrollbar-track{background:transparent}::-webkit-scrollbar-thumb{background:var(--bdr);border-radius:3px}::-webkit-scrollbar-thumb:hover{background:var(--t3)}
     .term-close{margin-left:auto;width:18px;height:18px;border-radius:4px;display:flex;align-items:center;justify-content:center;font-size:10px;color:var(--t3);cursor:pointer;flex-shrink:0;transition:all .1s}.term-close:hover{color:var(--err);background:rgba(248,81,73,.15)}


