 function termSendInput(ws, data) {
   if (!ws || ws.readyState !== 1 || !data) return;
   const MAX = 8192;
   if (data.length <= MAX) {
     ws.send(JSON.stringify({ type: 'input', data: data }));
     return;
   }
   let i = 0;
   const step = () => {
     if (ws.readyState !== 1) return;
     ws.send(JSON.stringify({ type: 'input', data: data.slice(i, i + MAX) }));
