 // Удаление репозитория — то же, что и на десктопе, но здесь есть
 // повод копия. Поэтому имя репозитория нада #1ывает нет, пока имя
 // совпадает с ним.
 let ghDeleteFullName = null;
 // The on-screen keyboard capitalises the first letter of every word, so what
 // actually lands in the box is "Sj0404-collab/Zen-panel". Compared case
 // sensitively against "sj0404-collab/zen-panel" it never matches, so the
 // button stayed grey for good — no request, no error, nothing happened. GitHub
 // repo names are case-insensitive anyway, so compare them that way, accept the
 // bare repo name too, and say out loud whether it matches instead of leaving
 // the user to guess why the button is dead.
 function delrepoTyped(fullName, v) {
   const t = String(v || '').trim().toLowerCase();
   if (!t) return false;
   return t === String(fullName).toLowerCase()
     || t === String(fullName).split('/').pop().toLowerCase();
 }
 function delrepoVerdict(fullName) {
   const el = document.getElementById('delrepo-verdict');
   if (!el) return;
   const t = String((document.getElementById('delrepo-confirm') || {}).value || '').trim();
   el.style.color = delrepoTyped(fullName, t) ? 'var(--ok,#3fb950)' : 'var(--t2)';
   el.textContent = !t ? 'ждём: ' + fullName
     : delrepoTyped(fullName, t) ? '✓ совпадает — можно удалять'
     : 'пока не совпадает с ' + fullName;
 }
 function ghDeleteRepoModal(fullName) {
   ghDeleteFullName = fullName;
   const info = document.getElementById('delrepo-info');
   if (info) info.textContent = 'Вы уверены, что хотите удалить ' + fullName + '?';
   const input = document.getElementById('delrepo-confirm');
   const btn = document.getElementById('delrepo-btn');
   if (input) {
     input.value = '';
     input.oninput = function () { if (btn) btn.disabled = !delrepoTyped(fullName, this.value); delrepoVerdict(fullName); };
   }
   if (btn) { btn.disabled = true; btn.textContent = 'Удалить навсегда'; }
   delrepoVerdict(fullName);
   const bg = document.getElementById('modal-delrepo');
   if (bg) bg.classList.add('on');
   // The backdrop is wired once for every modal at the bottom of this file, so
   // tapping outside closes this one too.
   if (input) setTimeout(() => input.focus(), 50);
 }
 async function confirmDeleteRepo() {
   const btn = document.getElementById('delrepo-btn');
   if (!btn || !ghDeleteFullName) return;
   const target = ghDeleteFullName;
   btn.disabled = true;
   btn.textContent = 'Удаляю...';
   try {
     const r = await fetch('/api/gh/delete-repo', {
       method: 'POST',
       headers: { 'Content-Type': 'application/json' },
       body: JSON.stringify({ full_name: target })
     });
     const d = await r.json();
     closeModal('modal-delrepo');
     if (d.success) {
       // В списке бы мог открываемуся - иначе увидим выше, что больше не выжидается
       // на месте и не доводит до конца работы.
       if (ghCurrentRepo === target) ghBackToList();
       if (typeof fmInfo === 'function') fmInfo('✅ Репозиторий ' + target + ' удалён.');
       ghLoadRepos();
     } else {
       if (typeof fmInfo === 'function') fmInfo('❌ ' + (d.error || 'не удалось'));
       btn.textContent = 'Удалить навсегда';
       btn.disabled = false;
     }
   } catch (e) {
     if (typeof fmInfo === 'function') fmInfo('❌ ' + e.message);
     btn.textContent = 'Удалить навсегда';
     btn.disabled = false;
   }
 }

 async function ghQuickClone(full_name){
   ghCurrentRepo=full_name;
   // Для списка — сразу Terminal (быстро), а выбор — через деталку
   // Но показываем то же меню рядом с кнопкой
   const fakeEvent={stopPropagation:()=>{}, target:document.getElementById('gh-agent-menu')};
   // Если много инструментов — покажем меню, иначе сразу клон
   const inst=(typeof tools!=='undefined'?tools:[]).filter(t=>t.installed);
   if(inst.length>1){
     // Откроем меню в шапке деталки, но сначала покажем деталку? проще — сразу клон в терминал
     if(typeof fmInfo==='function') fmInfo('⏳ Клонирую '+full_name+' в Terminal...');
     try{
       const r=await fetch('/api/gh/clone',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({full_name})}).then(x=>x.json());
       if(!r.success){ if(typeof fmInfo==='function') fmInfo('❌ '+(r.error||'')); return; }
       if(typeof showPage==='function') showPage('terminal');
       if(typeof createTerm==='function') createTerm('_terminal', r.path);
