 // ===== RUNNER CARD — сохранение / выключение / перезапуск ранера =====
 let RUNNER = null;        // last /api/runner answer
 let RUNNER_BUSY = false;  // stop/restart in flight
 let RUNNER_ASKED = false; // /api/runner already asked, so a failed hub is not re-asked on every render
 let HO_MORE = false;      // the folded relay settings, same reason
 function fmtBytes(n) {
   if (n == null) return '?';
   if (n < 1024) return n + ' B';
   if (n < 1048576) return (n / 1024).toFixed(1) + ' KB';
   if (n < 1073741824) return (n / 1048576).toFixed(1) + ' MB';
   return (n / 1073741824).toFixed(2) + ' GB';
 }
 function dlNow(url, name) {
   try {
     const a = document.createElement('a');
     a.href = url; a.download = name || '';
     document.body.appendChild(a); a.click(); a.remove();
   } catch (e) { fmInfo('Скачать вручную: ' + url); }
 }
 function runnerRender() {
   const el = document.getElementById('runner-card');
   if (!el) return;
   const onActs = !!(RUNNER && RUNNER.success && RUNNER.actions);
   const env = RUNNER && RUNNER.success ? RUNNER : null;
   // Three states, not two. RUNNER === null used to be printed as "PC-local"
   // with both buttons greyed out — but null only means nobody has asked the hub
   // yet, and nobody ever did, so the card arrived dead (see RUNNER_ASKED).
   const info = !env
     ? 'Спрашиваю хаб…'
     : onActs
       ? `<b>${escHtml(env.repo || '?')}</b> #${escHtml(env.runNumber || '')} · ${escHtml(env.os || '')} · ${escHtml(env.workflowFile || env.workflow || '')}`
         + (env.hostname ? ' · ' + escHtml(env.hostname) : '')
         + (env.workDir ? '<br>' + escHtml(env.workDir) : '')
         + (env.tunnel ? '<br>🌐 ' + escHtml(env.tunnel) : '')
       : `<b>PC-local</b> · ${escHtml(env.os || '')} · ${escHtml(env.hostname || '')}`
         + (env.workDir ? '<br>📂 ' + escHtml(env.workDir) : '')
         + (env.tunnel ? '<br>🌐 ' + escHtml(env.tunnel) : '')
         + '<br>«Сохранить» работает и здесь. «Выключить» отменяет прогон GitHub Actions — на локальном хабе отменять нечего.';
   el.innerHTML = `<div class="runner-box">
     <div class="runner-h">🎛 Раннер <span class="runner-dot${onActs ? ' on' : ''}"></span></div>
     <div class="runner-line">${info}</div>
     <div class="runner-btns">
       <button class="btn btn-sm btn-ok" onclick="runnerSave()" id="runner-save" disabled>💾 Сохранить</button>
       <button class="btn btn-sm btn-er" onclick="runnerStop()" id="runner-stop"${onActs ? '' : ' disabled title="Отменяет прогон GitHub Actions — доступно только на Actions-раннере"'}>⏻ Выключить</button>
     </div>
     <div id="runner-scan"></div>
     <div id="runner-res"></div>
     <div class="runner-h" style="margin-top:10px">🔁 Эстафета <span class="runner-dot" id="handoff-dot"></span></div>
     <div class="runner-line" id="handoff-line">загружаю состояние…</div>
     <div class="runner-btns">
       <button class="btn btn-sm btn-ok" onclick="handoffStart()" id="ho-start">🔁 Передать</button>
       <button class="btn btn-sm btn-ok" onclick="handoffContinue()" id="ho-continue" hidden>▶️ Продолжить</button>
       <details class="more" id="ho-more" ontoggle="HO_MORE=this.open">
         <summary id="ho-more-sum">⚙️ Автопередача и лимиты</summary>
         <div class="runner-btns" style="margin:8px 0 0">
           <label class="runner-lbl"><input id="ho-auto" type="checkbox"> автопередача</label>
           <label class="runner-lbl">работает до <input id="ho-age" class="runner-inp" type="number" min="0" max="720" step="10" inputmode="numeric"> мин</label>
           <label class="runner-lbl">простой <input id="ho-idle" class="runner-inp" type="number" min="0" max="720" step="5" inputmode="numeric"> мин</label>
           <label class="runner-lbl">отсчёт <input id="ho-count" class="runner-inp" type="number" min="30" max="1800" step="30" inputmode="numeric"> с</label>
           <button class="btn btn-sm" onclick="handoffSave()">💾 Лимиты</button>
         </div>
         <div class="runner-line" style="font-size:11px;opacity:.7;margin:8px 0 0" id="handoff-hint"></div>
       </details>
     </div>
   </div>`;
   // The card is rebuilt on every scan and install, so a fold the user opened
   // would snap shut under their finger. Put it back the way they left it.
   const hoMore = document.getElementById('ho-more');
   if (hoMore && HO_MORE) hoMore.open = true;
   handoffRender();
   if (RUNNER_BUSY) {
     const s = document.getElementById('runner-scan');
     if (s) s.innerHTML = '<div class="runner-busy">работаю…</div>';
   }
   // Ask once. The only thing that ever called /api/runner was the «Сканировать»
   // button q101 deleted, so opening the tab rendered a card with no state and
   // no way to get one: both buttons stayed grey for good. One fetch fixes it.
   if (!RUNNER && !RUNNER_ASKED) { RUNNER_ASKED = true; setTimeout(runnerScan, 0); }
 }

 // ===== ЭСТАФЕТА СЕССИИ (handoff) =====
 // Рано или поздно GitHub-hosted раннер умирает вместе со всем диском. Здесь
 // видно, что происходит: два лимита (возраст сессии и простой), обязательное
 // сохранение перед передачей, отсчёт с кнопкой «Продолжить» и состояние
 // «ждём новый раннер». Настройки лежат в control-репозитории, поэтому новый
 // раннер читает их сам.
 let HANDOFF = null;
 let HANDOFF_TIMER = null;
 const HANDOFF_TEXT = {
   idle: 'спокойно — передача не нужна',
   saving: 'сохраняю всё на GitHub…',
   countdown: 'скоро передам сессию следующему раннеру',
   dispatching: 'запускаю следующий раннер…',
   standby: 'новый раннер запущен, жду его адрес…',
   stopping: 'новый раннер готов — этот отключается',
   failed: 'не получилось передать — остаёмся здесь'
 };
 const HANDOFF_WHY = {
   age: 'пора: раннер скоро умрёт от лимита GitHub',
   idle: 'пора: давно ничего не делали',
   manual: 'передача по кнопке',
   retry: 'повтор после неудачи'
 };
 function handoffRender() {
   const line = document.getElementById('handoff-line');
   if (!line || !HANDOFF) return;
   const s = HANDOFF.status || {};
   const p = HANDOFF.policy || {};
   const cap = HANDOFF.capability || {};
   const mmss = (sec) => {
     sec = Math.max(0, Math.round(sec || 0));
     return Math.floor(sec / 60) + ':' + String(sec % 60).padStart(2, '0');
   };
   const bits = [];
   bits.push('<b>' + escHtml((HANDOFF_TEXT[s.state] || s.state || '—')) + '</b>');
   if (s.state === 'countdown' && s.leftSec != null) bits.push('осталось <b>' + mmss(s.leftSec) + '</b>');
   if (s.reason) bits.push(escHtml(HANDOFF_WHY[s.reason] || s.reason));
   if (s.state === 'failed' && s.lastError) bits.push('<span style="color:var(--err)">' + escHtml(s.lastError) + '</span>');
   if (s.successor && s.successor.url) bits.push('новый: <a href="' + escAttr(s.successor.url) + '" target="_blank" rel="noreferrer">' + escHtml(s.successor.url) + '</a>');
   bits.push('раннер живёт ' + (s.ageMin || 0) + ' мин' + (p.idleMin > 0 ? ', простой ' + (s.idleMin || 0) + '/' + p.idleMin + ' мин' : ''));
   line.innerHTML = bits.join(' · ');
   const dot = document.getElementById('handoff-dot');
   if (dot) dot.className = 'runner-dot' + (cap.available && s.state !== 'idle' ? ' on' : '');
   const set = (id, v) => { const el = document.getElementById(id); if (el && document.activeElement !== el) el.value = v; };
   set('ho-age', p.maxAgeMin == null ? '' : p.maxAgeMin);
   set('ho-idle', p.idleMin == null ? '' : p.idleMin);
   set('ho-count', p.countdownSec == null ? '' : p.countdownSec);
   const autoBox = document.getElementById('ho-auto');
   if (autoBox && document.activeElement !== autoBox) autoBox.checked = p.auto === true || p.auto === 1;
   // The switch and the limits are folded away, so the summary carries their
   // state instead of adding another line to the card.
   const sum = document.getElementById('ho-more-sum');
   if (sum) sum.textContent = '⚙️ Автопередача и лимиты — ' + (s.enabled ? 'включена' : 'выключена') +
     (s.savedIn ? ' · ' + (s.savedIn === 'repo' ? 'в репозитории' : 'локально') : '');
   const cont = document.getElementById('ho-continue');
   if (cont) cont.hidden = !(s.state === 'countdown' || s.state === 'failed');
   const start = document.getElementById('ho-start');
   if (start) start.disabled = !cap.available || s.state === 'saving' || s.state === 'standby' || s.state === 'stopping';
   const hint = document.getElementById('handoff-hint');
   if (hint) hint.textContent = !cap.available
     ? (cap.reason || 'передача недоступна')
     : '0 = выключено. Без «автопередачи» новый раннер не запускается сам — только по кнопке. всё на GitHub и только потом считает 3 минуты; «Продолжить» отменяет.';
 }
 async function handoffPoll() {
   try {
     const r = await fetch('/api/handoff').then(x => x.json());
     if (r && r.success) { HANDOFF = r; handoffRender(); }
   } catch (e) { /* the runner may be restarting */ }
 }
 function handoffPollStart() {
   handoffPoll();
   if (!HANDOFF_TIMER) HANDOFF_TIMER = setInterval(handoffPoll, 12000);
 }
 async function handoffSave() {
   const num = (id, def) => { const v = parseInt((document.getElementById(id) || {}).value, 10); return Number.isFinite(v) ? v : def; };
   const r = await fetch('/api/handoff/policy', {
     method: 'POST', headers: { 'Content-Type': 'application/json' },
     body: JSON.stringify({ policy: { auto: !!((document.getElementById('ho-auto') || {}).checked), maxAgeMin: num('ho-age', 0), idleMin: num('ho-idle', 0), countdownSec: num('ho-count', 180) } })
   }).then(x => x.json()).catch(e => ({ success: false, error: e.message }));
   if (r && r.policy) HANDOFF = Object.assign({}, HANDOFF || {}, { policy: r.policy, status: r.status || (HANDOFF && HANDOFF.status) });
   const hint = document.getElementById('handoff-hint');
   if (hint) hint.textContent = r && r.success
     ? 'сохранено: ' + (r.savedIn === 'repo' ? 'в control-репозитории (переживёт смену раннера)' : 'локально (нет токена GitHub)')
     : 'не сохранилось: ' + ((r && r.error) || '?');
   handoffPoll();
 }
 async function handoffStart() {
   if (!(await fmConfirm('Передать сессию новому раннеру? Сначала всё сохранится на GitHub, потом 3 минуты на отмену.', 'Передать'))) return;
   const r = await fetch('/api/handoff/start', { method: 'POST' }).then(x => x.json()).catch(e => ({ success: false, error: e.message }));
   if (r && r.status) { HANDOFF = Object.assign({}, HANDOFF || {}, { status: r.status }); handoffRender(); }
   if (r && !r.success) { const hint = document.getElementById('handoff-hint'); if (hint) hint.textContent = (r.reason || r.error || 'не вышло'); }
 }
 async function handoffContinue() {
   const r = await fetch('/api/handoff/continue', { method: 'POST' }).then(x => x.json()).catch(e => ({ success: false, error: e.message }));
   if (r && r.status) { HANDOFF = Object.assign({}, HANDOFF || {}, { status: r.status }); handoffRender(); }
 }
 async function runnerScan() {
   const w = document.getElementById('runner-scan');
   if (w) w.innerHTML = '<div class="runner-busy">сканирую…</div>';
   let r = null;
   try { r = await fetch('/api/runner').then(x => x.json()); } catch (e) { r = { success: false, error: e.message }; }
   RUNNER = r;
   runnerRender();
   if (!r.success) { if (w) w.innerHTML = '<div class="runner-err">' + escHtml(r.error || 'нет ответа') + '</div>'; return; }
   const items = [];
   (r.apks || []).forEach(a => items.push({ kind: 'apk', name: a.name, path: a.path, size: a.size, isDir: false }));
   (r.folders || []).forEach(f => items.push({ kind: 'folder', name: f.name, path: f.path, size: f.size, isDir: true }));
   const saveBtn = document.getElementById('runner-save');
   if (!items.length) {
     if (w) w.innerHTML = '<div class="runner-err">Ничего не нашлось в ~/hub-work. Положи файлы туда вкладкой «Файлы» (⬆), потом сканируй снова.</div>';
     if (saveBtn) saveBtn.disabled = true;
     return;
   }
   if (w) w.innerHTML = `<div class="runner-list">` + items.map((it) => `
     <div class="runner-item">
       <div>${it.kind === 'apk' ? '📦' : '📁'}</div>
       <div class="runner-name" title="${escAttr(it.path)}">${escHtml(it.name)}<span class="runner-meta">${fmtBytes(it.size)} · ${it.kind === 'apk' ? 'APK' : 'папка'}</span></div>
       <select class="runner-dest" data-path="${escAttr(it.path)}" data-dir="${it.isDir ? '1' : ''}">
         <option value="phone"${it.kind === 'apk' ? ' selected' : ''}>на телефон</option>
         <option value="branch"${it.kind === 'folder' ? ' selected' : ''}>в ветку (tar.xz)</option>
         <option value="keep">оставить</option>
         <option value="skip">пропустить</option>
       </select>
     </div>`).join('') + `</div>`;
   if (saveBtn) saveBtn.disabled = false;
 }
 async function runnerSave() {
   const saveBtn = document.getElementById('runner-save');
   if (saveBtn && saveBtn.disabled) return;
   const items = [], dl = [];
   document.querySelectorAll('.runner-dest').forEach(sel => {
     const dest = sel.value;
     if (dest === 'skip') return;
     items.push({ path: sel.dataset.path, dest });
     if (dest === 'phone') {
       const nm = String(sel.dataset.path).split(/[/\\]/).pop();
       dl.push({ path: sel.dataset.path, name: nm + (sel.dataset.dir ? '.tar.xz' : ''), isDir: !!sel.dataset.dir });
     }
   });
   if (!items.length) return;
   if (saveBtn) saveBtn.disabled = true;
   let r = await HubOffline.post('/api/runner/backup', { items }, 'отправить в ветку');
   const out = document.getElementById('runner-res');
   if (r.queued) {
     if (out) out.innerHTML = '<div class="runner-res">⏳ Нет связи — отправка в ветку в очереди, уйдёт автоматически, когда связь вернётся.</div>';
     if (saveBtn) saveBtn.disabled = false;
     return;
   }
   if (!r.success) {
     if (out) out.innerHTML = '<div class="runner-err">' + escHtml(r.error || 'ошибка') + '</div>';
     if (saveBtn) saveBtn.disabled = false;
     return;
   }
   const lines = (r.results || []).map(x => {
     if (x.ok && x.action === 'branch') return '✓ <b>' + escHtml(x.name || '') + '</b> → <a href="' + escAttr(x.url || '#') + '" target="_blank" rel="noreferrer">в ветке</a>';
     if (x.ok && x.action === 'phone') return '⬇ <b>' + escHtml(x.name || '') + '</b> — скачивается…';
     if (x.ok && x.action === 'keep') return '○ <b>' + escHtml(x.name || '') + '</b> — остался на ранере';
     return '✗ ' + escHtml(x.name || '') + ': ' + escHtml(x.error || '?');
   });
   if (out) { out.innerHTML = '<div class="runner-res">' + lines.join('<br>') + '</div>'; setTimeout(() => { out.innerHTML = ''; }, 25000); }
   dl.forEach(d => dlNow(d.isDir ? '/api/fs/archive?path=' + encodeURIComponent(d.path) : '/api/fs/download?path=' + encodeURIComponent(d.path), d.name));
   if (saveBtn) saveBtn.disabled = false;
   runnerScan();
 }
 function runnerVisible() { return !!(RUNNER && RUNNER.success && RUNNER.actions && !RUNNER_BUSY); }
 async function runnerStop() {
   if (!runnerVisible()) { fmInfo('Кнопки активны только на Actions-раннере.'); return; }
   if (!(await fmConfirm('Выключить ранер? Всё, что не сохранили, пропадёт при его смерти. Сначала «💾 Сохранить».', 'Выключить'))) return;
   RUNNER_BUSY = true; runnerRender();
   const r = await fetch('/api/runner/stop', { method: 'POST' }).then(x => x.json()).catch(e => ({ success: false, error: e.message }));
   RUNNER_BUSY = false; runnerRender();
   const out = document.getElementById('runner-res');
   if (out) out.innerHTML = r.success
     ? '<div class="runner-res">⏻ Остановка принята — ранер сворачивается ~минуту.</div>'
     : '<div class="runner-err">' + escHtml(r.error || 'не вышло') + '</div>';
 }

 function toggleApplyMenu(e, toolId) {
   e.stopPropagation();
   document.querySelectorAll('.apply-menu').forEach(m => m.classList.remove('on'));
   const menu = document.getElementById('amenu-' + toolId);
   if (!menu) return;
   const dir = document.getElementById('cdir-' + toolId)?.value?.trim() || homeDir;
   menu.innerHTML = `<div class="apply-menu-title">Запустить в</div>` +
     tools.filter(t => t.installed).map(t => `
     <div class="apply-item" onclick="event.stopPropagation();openFromCard('${toolId}','${escAttr(dir)}','${t.id}')">
