     .term-recover b{margin-left:6px;background:var(--acc);color:#0d1117;border-radius:7px;padding:7px 12px;font-weight:700;white-space:nowrap;cursor:pointer}
     .term-recover b:active{opacity:.8}
     .sess-clock.bad{color:var(--err);background:rgba(248,81,73,.12);font-weight:700}
     .access-badge{font-size:11px;padding:4px 10px;border-radius:10px;font-weight:600}
     .access-local{color:var(--ok);background:rgba(63,185,80,.12)}
     .access-remote{color:var(--warn);background:rgba(210,153,34,.12)}
     .tunnel-badge{color:#bc8cff;background:rgba(188,140,255,.12);font-size:11px;padding:4px 10px;border-radius:10px;font-weight:600;cursor:pointer;text-decoration:none}
     .tunnel-url{font-size:10px;color:var(--pur);cursor:pointer;text-decoration:underline;text-underline-offset:2px}
     .btn{padding:8px 14px;border-radius:8px;border:1px solid var(--bdr);background:var(--bg4);color:var(--t1);font-size:14px;cursor:pointer;transition:all .12s;white-space:nowrap;-webkit-tap-highlight-color:transparent}
     .btn:active{background:var(--bdr)}.btn-p{background:var(--acc);color:#fff;border-color:var(--acc)}.btn-p:active{opacity:.85}
     .btn-ok{background:var(--ok);color:#fff;border-color:var(--ok)}.btn-er{background:var(--err);color:#fff;border-color:var(--err)}
     .btn-sm{padding:6px 10px;font-size:12px}
     .btn-icon{width:40px;height:40px;padding:0;display:flex;align-items:center;justify-content:center;font-size:18px;border-radius:10px}

     /* ===== SIDEBAR DRAWER ===== */
     .drawer-overlay{display:none;position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:90}
     .drawer-overlay.on{display:block}
     .drawer{position:fixed;top:0;bottom:0;left:-280px;width:280px;background:var(--bg1);border-right:1px solid var(--bdr);z-index:95;display:flex;flex-direction:column;transition:left .25s ease;padding-top:env(safe-area-inset-top)}
     .drawer.on{left:0}
     .drawer-header{display:flex;align-items:center;justify-content:space-between;padding:14px 12px;border-bottom:1px solid var(--bdr)}
     .drawer-header .title{font-size:14px;font-weight:700}
     .drawer-close{width:32px;height:32px;border-radius:8px;border:1px solid var(--bdr);background:var(--bg3);color:var(--t2);font-size:16px;cursor:pointer;display:flex;align-items:center;justify-content:center}
     .drawer-body{flex:1;overflow-y:auto;padding:8px;-webkit-overflow-scrolling:touch}
     .sb-lbl{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.7px;color:var(--t3);margin:12px 0 6px;padding:0 8px}
     .sb-i{display:flex;align-items:center;gap:10px;padding:10px 10px;border-radius:8px;cursor:pointer;font-size:13px;color:var(--t2);transition:all .1s;border:1px solid transparent;-webkit-tap-highlight-color:transparent}
     .sb-i:active{background:var(--bg3);color:var(--t1)}.sb-i.on{background:var(--bg3);color:var(--acc);border-color:var(--bdr)}
     .sb-ico{width:24px;height:24px;border-radius:6px;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:800;flex-shrink:0}
     .drawer-actions{padding:10px;border-top:1px solid var(--bdr);display:flex;gap:8px;padding-bottom:max(10px,env(safe-area-inset-bottom))}
     .drawer-actions .btn{flex:1;text-align:center;padding:10px;font-size:13px}

     /* ===== MAIN CONTENT ===== */
     .main{flex:1;display:flex;flex-direction:column;overflow:hidden}
     .content{flex:1;display:flex;flex-direction:column;overflow:hidden;-webkit-overflow-scrolling:touch}
     .page{display:none;flex:1;overflow-y:auto;padding:14px;-webkit-overflow-scrolling:touch}.page.on{display:flex;flex-direction:column}

     /* ===== BOTTOM NAV ===== */
     .bottom-nav{height:60px;background:var(--bg2);border-top:1px solid var(--bdr);display:flex;flex-shrink:0;padding-bottom:env(safe-area-inset-bottom)}
-    .nav-btn{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;background:none;border:none;color:var(--t3);font-size:10px;cursor:pointer;-webkit-tap-highlight-color:transparent;transition:all .1s}
+    .nav-btn{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;background:none;border:none;color:var(--t3);font-size:10px;cursor:pointer;-webkit-tap-highlight-color:transparent;transition:all .1s;text-decoration:none}
     .nav-btn:active{background:var(--bg4)}
     .nav-btn.on{color:var(--acc)}
     .nav-ico{font-size:22px;line-height:1}
     .nav-label{font-size:10px;font-weight:500}

     /* ===== DASHBOARD ===== */
     .ph h1{font-size:22px;font-weight:700;margin-bottom:4px}.ph p{font-size:13px;color:var(--t2);margin-bottom:16px}
     .stats{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin-bottom:16px}
     .st{background:var(--bg3);border:1px solid var(--bdr);border-radius:10px;padding:14px;text-align:center}
     .st-v{font-size:28px;font-weight:800}.st-l{font-size:11px;color:var(--t2);margin-top:2px}
     .grid{display:grid;grid-template-columns:1fr;gap:10px}
     /* ===== RUNNER CARD ===== */
     #runner-card{margin-top:12px}
     .runner-box{background:var(--bg3);border:1px solid var(--bdr);border-radius:12px;padding:14px}
     .runner-h{display:flex;align-items:center;gap:8px;font-size:14px;font-weight:800;margin-bottom:8px}
     .runner-dot{width:8px;height:8px;border-radius:50%;background:var(--t3)}
     .runner-dot.on{background:var(--ok);box-shadow:0 0 8px rgba(63,185,80,.6)}
     .runner-line{font-size:11.5px;color:var(--t2);margin-bottom:10px;word-break:break-all}
     .runner-line b{color:var(--t1)}
     .runner-btns{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px}
     /* Эстафета: два лимита + отсчёт вводим прямо в карточке раннера. */
     .runner-lbl{display:flex;align-items:center;gap:4px;font-size:11px;color:var(--t3)}
     .runner-inp{width:58px;padding:6px 8px;background:var(--bg0);border:1px solid var(--bdr);border-radius:8px;color:var(--t1);font-size:13px;font-family:monospace;outline:none}
     .runner-inp:focus{border-color:var(--acc)}
     .runner-list{display:flex;flex-direction:column;gap:6px;margin-bottom:8px}
     .runner-item{display:flex;align-items:center;gap:8px;background:var(--bg2);border:1px solid var(--bdr);border-radius:8px;padding:8px}
     .runner-item select{flex:0 0 118px;padding:6px;font-size:11.5px;background:var(--bg0);border:1px solid var(--bdr);border-radius:6px;color:var(--t1);outline:none}
     .runner-name{flex:1;min-width:0;font-size:12px;word-break:break-word}
     .runner-meta{display:block;font-size:10px;color:var(--t3);margin-top:2px}
     .runner-res{font-size:12px;color:var(--ok);background:rgba(63,185,80,.08);border:1px solid rgba(63,185,80,.3);border-radius:8px;padding:8px;margin-bottom:8px}
     .runner-res a{color:var(--acc)}
     .runner-err{font-size:12px;color:var(--err);background:rgba(248,81,73,.08);border:1px solid rgba(248,81,73,.3);border-radius:8px;padding:8px;margin-bottom:8px}
     .runner-busy{font-size:12px;color:var(--warn);margin-bottom:8px}
     .card{background:var(--bg3);border:1px solid var(--bdr);border-radius:12px;padding:16px}
     .card-h{display:flex;align-items:center;gap:12px;margin-bottom:10px}
     .card-ico{width:40px;height:40px;border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:800}
     .card-n{font-size:15px;font-weight:600}.card-v{font-size:10px;color:var(--t3);font-family:monospace}
     .tag{font-size:10px;padding:3px 8px;border-radius:8px;display:inline-block;margin-right:4px}
     .tag-on{color:var(--ok);background:rgba(63,185,80,.12)}.tag-off{color:var(--err);background:rgba(248,81,73,.12)}
     .mini-badge{font-size:8px;font-weight:700;padding:2px 6px;border-radius:4px;border:1px solid;margin-left:4px;vertical-align:2px}
     .card-badges{height:16px;display:flex;gap:4px;overflow:hidden}
     .test-res{font-size:10px;color:var(--t3);min-height:14px;padding:5px 0 0;font-family:monospace;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
     .card-foot{display:flex;align-items:center;gap:8px;margin-top:12px;padding-top:10px;border-top:1px solid var(--bdr)}
     .card-dir{flex:1;font-size:14px;color:var(--t2);font-family:monospace;padding:8px 10px;background:var(--bg0);border:1px solid var(--bdr);border-radius:6px;outline:none;color:var(--t1);width:100%}
     .card-dir:focus{border-color:var(--acc)}
     .apply-menu{display:none;position:fixed;bottom:70px;left:10px;right:10px;background:var(--bg2);border:1px solid var(--bdr);border-radius:12px;min-width:200px;z-index:50;box-shadow:0 -4px 24px rgba(0,0,0,.5);max-height:60vh;overflow-y:auto}
     .apply-menu.on{display:block}
     .apply-menu-title{padding:12px 14px;font-size:13px;font-weight:600;border-bottom:1px solid var(--bdr);color:var(--t2)}
     .apply-item{display:flex;align-items:center;gap:10px;padding:12px 14px;cursor:pointer;font-size:14px;color:var(--t2);border-bottom:1px solid var(--bdr);-webkit-tap-highlight-color:transparent}
     .apply-item:last-child{border-bottom:none}
     .apply-item:active{background:var(--bg3);color:var(--t1)}

     /* ===== TERMINAL ===== */
     .term-page{display:none;flex:1;flex-direction:column;overflow:hidden}.term-page.on{display:flex}
     .term-topbar{display:flex;align-items:center;background:var(--bg1);border-bottom:1px solid var(--bdr);flex-shrink:0}
     .tabs-row{display:flex;overflow-x:auto;flex:1;-webkit-overflow-scrolling:touch;touch-action:pan-x pan-y;overscroll-behavior:contain}
     .tab{display:flex;align-items:center;gap:6px;padding:10px 14px;font-size:13px;color:var(--t2);cursor:pointer;border-bottom:2px solid transparent;white-space:nowrap;flex-shrink:0;-webkit-tap-highlight-color:transparent}
     .tab:active{background:var(--bg3)}.tab.on{color:var(--acc);border-bottom-color:var(--acc);background:var(--bg2)}
     .tab-dot{width:8px;height:8px;border-radius:50%;flex-shrink:0}
     .tab-x{margin-left:4px;opacity:.4;font-size:15px}.tab-x:active{opacity:1;color:var(--err)}
     .tab-add{padding:10px 12px;color:var(--t3);cursor:pointer;font-size:18px;flex-shrink:0}.tab-add:active{color:var(--acc)}
     .term-controls{display:flex;align-items:center;gap:6px;padding:0 10px;border-left:1px solid var(--bdr);flex:0 1 auto;min-width:0;overflow-x:auto;-webkit-overflow-scrolling:touch;touch-action:pan-x;overscroll-behavior:contain;scrollbar-width:none}
     .term-controls::-webkit-scrollbar{display:none}
     .term-controls>*{flex-shrink:0}
     .tc-btn{width:36px;height:36px;border-radius:8px;border:1px solid var(--bdr);background:var(--bg3);color:var(--t2);font-size:16px;cursor:pointer;display:flex;align-items:center;justify-content:center;-webkit-tap-highlight-color:transparent}
     .tc-btn:active{background:var(--bdr);color:var(--t1)}.tc-btn,.arr-btn{-webkit-user-select:none;user-select:none;-webkit-touch-callout:none}
     .tc-btn:focus{outline:none;-webkit-tap-highlight-color:transparent}
     .zoom-label{font-size:12px;color:var(--t3);min-width:44px;text-align:center;font-family:monospace}
     .term-container{flex:1;display:flex;overflow:hidden;background:#000;flex-direction:column;flex-wrap:nowrap;position:relative}
     .term-arrows{position:absolute;bottom:8px;right:8px;z-index:2;display:flex;flex-direction:column;align-items:center;gap:4px;opacity:.7;transition:opacity .2s}
     .term-arrows:active{opacity:1}
     .arr-row{display:flex;gap:4px}
     .arr-btn{width:42px;height:42px;border-radius:8px;border:1px solid rgba(255,255,255,.2);background:rgba(255,255,255,.08);color:#e6edf3;font-size:16px;font-weight:700;cursor:pointer;display:flex;align-items:center;justify-content:center;-webkit-tap-highlight-color:transparent;touch-action:manipulation}
     .arr-btn:active{background:rgba(255,255,255,.25)}
     .arr-center{font-size:10px;width:52px}
     .arr-extra{display:flex;gap:4px;margin-top:2px}
     .arr-wide{width:auto;padding:0 14px;font-size:11px}
     .term-panel{display:none;flex:1;width:100%;flex-direction:column;overflow:hidden;border:1px solid var(--bdr);min-height:200px;position:relative}
     .term-panel.on{display:flex}
     .term-header{display:flex;align-items:center;justify-content:space-between;padding:6px 12px;background:var(--bg2);border-bottom:1px solid var(--bdr);flex-shrink:0}
     .term-header-title{font-size:11px;color:var(--t2);display:flex;align-items:center;gap:6px}
     .term-info{font-size:10px;color:var(--t3);font-family:monospace}
     .term{flex:1;background:#000;padding:2px;overflow:hidden}
     .term .xterm{height:100%}
     .term .xterm-viewport{overflow-y:auto!important;overflow-x:hidden!important;-webkit-overflow-scrolling:touch!important}.term .xterm-viewport{touch-action:pan-x pan-y!important}
     .term .xterm-viewport::-webkit-scrollbar{width:6px}
     .term .xterm-viewport::-webkit-scrollbar-track{background:transparent}
     .term .xterm-viewport::-webkit-scrollbar-thumb{background:var(--bdr);border-radius:3px}
     .term-wrap{flex:1;display:flex;flex-direction:row;overflow:hidden;min-width:0;position:relative}
     .term-wrap .term{flex:1;min-width:0}
     /* Виртуальная мышь терминала — та же, что на вкладке «Экран»: тянуть по
        подушечке = колесо мыши, ▲▼ = шаг, ⠿ тащит сам блок. По умолчанию
        плавает СВЕРХУ слева (свежий вывод терминала не перекрывается), в покое
        полупрозрачная; тап по ручке возвращает блок наверх. */
     .term-scroll{position:absolute;right:8px;top:8px;left:auto;z-index:4;display:flex;flex-direction:row;align-items:stretch;border-radius:10px;background:rgba(13,17,23,.72);border:1px solid rgba(240,246,252,.18);box-shadow:0 2px 8px rgba(0,0,0,.4);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);overflow:hidden;touch-action:none;opacity:.5;transition:opacity .15s ease,box-shadow .15s ease}
     .term-scroll.chasing{opacity:1;box-shadow:0 2px 12px rgba(0,0,0,.6),0 0 0 1px rgba(88,166,255,.35)}
     .term-mouse-pad{width:62px;height:58px;flex:0 0 auto;display:flex;align-items:center;justify-content:center;font-size:22px;line-height:1;color:rgba(230,237,243,.85);background:radial-gradient(circle at center,rgba(88,166,255,.18),rgba(255,255,255,.04) 62%,transparent 72%);border-right:1px solid rgba(240,246,252,.14);touch-action:none;cursor:grab;-webkit-user-select:none;user-select:none;-webkit-tap-highlight-color:transparent}
     .term-mouse-pad:active{cursor:grabbing;background-color:rgba(88,166,255,.14)}
     .term-mouse-wheel{display:flex;flex-direction:column;flex:0 0 auto}
     .term-scroll-arr{width:40px;height:29px;flex-shrink:0;border:none;background:transparent;color:#e6edf3;font-size:14px;line-height:1;cursor:pointer;touch-action:none;padding:0;flex:0 0 auto}
     .term-scroll-arr:active,.term-scroll-arr.on{background:var(--acc);color:#0d1117}
     .term-scroll-arr.dim{opacity:.35}
     .term-scroll-handle{width:17px;flex-shrink:0;border:none;background:rgba(255,255,255,.06);color:rgba(230,237,243,.8);font-size:12px;line-height:1;cursor:grab;touch-action:none;padding:0;align-self:stretch}
     .term-scroll-handle:active{cursor:grabbing}
     .term-scroll-track{display:none}
     .term-cd{display:none;position:absolute;left:12px;right:auto;bottom:12px;background:rgba(210,153,34,.14);border:1px solid var(--warn);color:var(--warn);border-radius:9px;font-size:12px;font-weight:700;font-family:monospace;padding:4px 10px;z-index:3;pointer-events:none;white-space:nowrap}
     .term-cd.on{display:block}

     /* ===== FILE MANAGER ===== */
     .fm-header{display:flex;gap:6px;padding:8px 0;margin-bottom:8px;flex-shrink:0;overflow-x:auto;-webkit-overflow-scrolling:touch;scrollbar-width:none;-ms-overflow-style:none;touch-action:pan-x pan-y;overscroll-behavior:contain}.fm-header::-webkit-scrollbar{display:none}
     .fm-header .btn{padding:8px 12px;font-size:13px}
     .fm-path-row{display:flex;gap:6px;margin-bottom:8px;flex-shrink:0}
     .fm-path-row input{flex:1;padding:8px 12px;background:var(--bg0);border:1px solid var(--bdr);border-radius:8px;color:var(--t1);font-size:14px;font-family:monospace;outline:none}
     .fm-path-row input:focus{border-color:var(--acc)}
     .fm-sidebar{max-height:140px;overflow-y:auto;background:var(--bg1);border:1px solid var(--bdr);border-radius:10px;margin-bottom:10px}
     .fm-sidebar-title{padding:8px 10px;font-size:10px;font-weight:700;text-transform:uppercase;color:var(--t3);border-bottom:1px solid var(--bdr)}
     .fm-sidebar-item{display:flex;align-items:center;gap:8px;padding:8px 10px;font-size:13px;color:var(--t2);cursor:pointer;border-bottom:1px solid var(--bdr);-webkit-tap-highlight-color:transparent}
     .fm-sidebar-item:active{background:var(--bg3)}
     .fm-list{flex:1;overflow-y:auto;border:1px solid var(--bdr);border-radius:10px;background:var(--bg0);-webkit-overflow-scrolling:touch}
     .fm-item{display:flex;align-items:center;gap:10px;padding:12px 14px;cursor:pointer;border-bottom:1px solid var(--bdr);-webkit-tap-highlight-color:transparent}
     .fm-item:active{background:var(--bg3)}.fm-item.fm-sel{background:rgba(88,166,255,.1)}
     .fm-ico{font-size:24px;flex-shrink:0;width:48px;text-align:center}
     .fm-name{flex:2;font-size:14px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
     .fm-size{font-size:11px;color:var(--t3);flex-shrink:0;min-width:60px;text-align:right}
     .fm-info{padding:6px 0;font-size:11px;color:var(--t3)}

     /* ===== MODELS FULL ===== */
     .models-full-actions{display:flex;gap:8px;margin-bottom:14px;flex-wrap:wrap}
     .models-full-actions .btn{font-size:13px;padding:8px 12px}
     #models-full-info{font-size:12px;color:var(--t3);display:flex;align-items:center}
     .tool-config-card{background:var(--bg3);border:1px solid var(--bdr);border-radius:12px;padding:14px;margin-bottom:10px}
     .tool-config-card .tc-name{font-size:14px;font-weight:600;margin-bottom:6px}
     .tool-config-card .tc-key{font-size:10px;color:var(--t3);font-family:monospace;word-break:break-all;margin-top:4px}
     .model-card{background:var(--bg3);border:1px solid var(--bdr);border-radius:12px;padding:14px;margin-bottom:10px}
     .model-card:active{border-color:var(--acc)}
     .model-card.selected{border-color:var(--ok);background:rgba(63,185,80,.05)}
     .model-card .model-name{font-size:14px;font-weight:600;margin-bottom:4px}
     .model-card .model-id{font-size:10px;color:var(--t3);font-family:monospace;word-break:break-all}

     /* ===== MODAL ===== */
     .modal-bg{display:none;position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:100;align-items:flex-end;justify-content:center;cursor:pointer}
     .modal-bg.on{display:flex}
     .modal{background:var(--bg2);border:1px solid var(--bdr);border-radius:16px 16px 0 0;padding:20px;width:100%;max-height:85dvh;display:flex;flex-direction:column}
     .modal h2{font-size:18px;font-weight:600;margin-bottom:14px}
     .modal-bar{display:flex;gap:8px;margin-bottom:12px}
     .modal-bar input{flex:1;padding:10px 12px;background:var(--bg0);border:1px solid var(--bdr);border-radius:8px;color:var(--t1);font-size:14px;font-family:monospace;outline:none}
     .modal-bar input:focus{border-color:var(--acc)}
     .modal-drives{display:flex;gap:6px;margin-bottom:12px;flex-wrap:wrap}
     .drive-btn{padding:8px 12px;background:var(--bg3);border:1px solid var(--bdr);border-radius:8px;color:var(--t2);font-size:13px;cursor:pointer;-webkit-tap-highlight-color:transparent}
     .drive-btn:active{border-color:var(--acc);color:var(--t1)}
     .git-pre{background:var(--bg0);border:1px solid var(--bdr);border-radius:8px;padding:12px;overflow:auto;max-height:50vh;font-size:12px;line-height:1.6;white-space:pre-wrap;word-break:break-all;-webkit-overflow-scrolling:touch}
     .git-file{display:flex;gap:8px;align-items:baseline;padding:4px 0;font-size:13px;font-family:monospace}
     .git-code{color:var(--warn);width:20px;flex-shrink:0}
     .modal-list{flex:1;overflow-y:auto;max-height:300px;border:1px solid var(--bdr);border-radius:8px;background:var(--bg0);-webkit-overflow-scrolling:touch}
     .modal-actions{display:flex;gap:8px;margin-top:14px;justify-content:flex-end}
     .modal-actions .btn{padding:10px 16px;font-size:14px}
     .newterm-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:14px}
     .newterm-tool{display:flex;align-items:center;gap:10px;padding:12px;background:var(--bg3);border:1px solid var(--bdr);border-radius:10px;cursor:pointer;-webkit-tap-highlight-color:transparent}
