+/* =========================================================================
+ * screen-app.js — страница «Экран» и её настройки (/linux).
+ *
+ * Экран и Настройки уехали сюда из хаба (npm-hub/public/mobile.html и
+ * desktop.html) по требованию владельца: рабочий стол — это ДРУГОЙ раннер,
+ * и npm-hub не должен поднимать его вместе с собой. Поэтому:
+ *
+ *   * в hub.yml остаётся только proxy-регистрация (/novnc + /ws/desktop),
+ *     а Xvfb/openbox/x11vnc поднимаются по первому открытию этой страницы
+ *     (POST /api/vnc/keepalive {action:'ensure'} в pageInit ниже);
+ *   * сюда переехало всё, что управляет экраном: автоподключение, полный
+ *     экран, зум/плавность, виртуальная мышь, звук видео, AVD, TTS/OCR;
+ *   * хаб сюда только ПЕРЕХОДИТ (/linux) и может передать ссылку, которую
+ *     надо открыть на столе (sessionStorage screen.pending_url).
+ *
+ * Код ниже переехал из mobile-app.js как есть; переписано ровно три вещи,
+ * которые на отдельной странице не имеют смысла: linuxOpen() больше не
+ * переключает вкладку, hubBrowserGo()/browserOpenDesktop() не уходят
+ * «в Экран» (он уже открыт), а fmInfo заменён на screenNote — хабового
+ * тоста на этой странице нет.
+ * ========================================================================= */
+
+// Тоста хаба здесь нет: страница отдельная, а fmInfo жил в mobile-app.js.
+// Пишем в ту же строку под панелью — пользователю нужно видеть, куда ушла
+// ссылка и что экран поднимается.
+function el2text(el, text) {
+  if (!el) return;
+  el.textContent = text;
+  el.className = 'tag tag-off';
+}
+
+function screenNote(text) {
+  const el = document.getElementById('linux-note');
+  if (el) { el.textContent = text; el.title = text; return; }
+  try { console.log('  🖥 ' + text); } catch {}
+}
+
+// Будим десктоп. Раньше он поднимался при старте хаба (vnc-keepalive.start),
+// теперь хаб только «взводит» маршруты, а стек экрана — здесь. Первый запуск
+// ставит desktop-стек (~минута), дальше это секунды; статус и плейсхолдер
+// показывают происходящее, поэтому ответ можно не ждать.
+async function screenWake() {
+  try {
+    const r = await fetch('/api/vnc/keepalive', {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ action: 'ensure' })
+    });
+    const d = await r.json().catch(() => null);
+    if (d && d.ok === false) screenNote('экран: ' + (d.error || 'не поднялся'));
+  } catch (e) {
+    try { screenNote('экран: хаб не отвечает — ' + (e && e.message || e)); } catch {}
+  }
+}
+
+// Ссылка, оставленная хабом (Files → «Открыть на экране», Git → 🌐, агент).
+// Открываем один раз и только когда экран реально готов: пока стек ставится,
+// /api/linux/run отвечает «pending», и окно потерялось бы.
+let pendingUrlChecked = false;
+function screenTakePendingUrl() {
+  if (pendingUrlChecked) return null;
+  pendingUrlChecked = true;
+  let url = '';
+  try { url = sessionStorage.getItem('screen.pending_url') || ''; } catch {}
+  if (!url) return null;
+  let vertical = false;
+  try { vertical = sessionStorage.getItem('screen.pending_vertical') === '1'; } catch {}
+  try {
+    sessionStorage.removeItem('screen.pending_url');
+    sessionStorage.removeItem('screen.pending_vertical');
+  } catch {}
+  return { url, vertical };
+}
+
+let pendingUrl = null;
+
+function pageInit() {
+  screenWake();
+  pendingUrl = screenTakePendingUrl();
+  // На телефоне стол сразу на весь экран — иначе мелкая картинка в рамке.
+  try { linuxOpen(); } catch {}
+  if (pendingUrl) {
+    const u = pendingUrl;
+    pendingUrl = null;
+    // Ждём готовности: linuxConnect() дёргает нас при появлении кадра.
+    screenPendingOpen = u;
+    screenNote('🖥 ' + u + ' → открою, как только экран поднимется');
+  }
+}
+let screenPendingOpen = null;
+
+// ===== LINUX DESKTOP: launch browser on VNC =====
+async function linuxRunBrowser(url, vertical) {
+  if (!url) return;
+  if (!/^https?:\/\//i.test(url)) url = 'https://' + url;
+  // This function is normally called by a tap on Go/YouTube; start the local
+  // audio receiver before the fetch so mobile autoplay rules allow playback.
+  try { remoteAudioStart(); } catch {}
+  try {
+    // mobile: хаб откроет окно размером с экран телефона в левом верхнем углу
+    // стола — телефон показывает стол крупно (1:1), и окно занимает весь экран.
+    const r = await fetch('/api/linux/run', {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ action: 'browser', url, vertical: !!vertical, mobile: true })
+    });
+    const d = await r.json();
+    if (!d.ok) console.warn('linuxRunBrowser:', d.error);
+  } catch (e) { console.warn('linuxRunBrowser failed:', e.message); }
+}
+
+// ===== PERSISTENT EMULATOR DEFAULT =====
+function emulatorDefaultInputId(prefix) { return prefix ? 'emulator-default-desktop' : 'emulator-default'; }
+async function loadEmulatorDefault(prefix) {
+  try {
+    const r = await fetch('/api/emulator/default');
+    const d = await r.json();
+    const el = document.getElementById(emulatorDefaultInputId(prefix));
+    if (el && d.emulator) el.value = d.emulator;
+  } catch {}
+}
+async function saveEmulatorDefault(prefix) {
+  const el = document.getElementById(emulatorDefaultInputId(prefix));
+  const emulator = String((el && el.value) || '').trim();
+  if (!emulator) return;
+  try {
+    const r = await fetch('/api/emulator/default', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ emulator }) });
+    const d = await r.json();
+    if (d.emulator && el) el.value = d.emulator;
+    const note = document.getElementById(prefix ? 'linux-note-desktop' : 'linux-note');
+    if (note) { note.textContent = 'AVD: ' + (d.emulator || d.error || 'ошибка'); setTimeout(() => { if (note.textContent.startsWith('AVD:')) note.textContent = ''; }, 3000); }
+  } catch {}
+}
+
+// ===== CLOUD PHONE =====
+function cloudPhoneUrl(suffix) {
+  const proto = location.protocol === 'https:' ? 'https' : 'http';
+  return proto + '://' + location.host + '/phone/' + (suffix || 'vnc.html');
+}
+function phoneMsg(msg) {
+  const el = document.getElementById('cp-status');
+  if (el) { el.textContent = msg; el.className = 'tag tag-off'; }
+}
+async function cloudPhoneStatus(prefix) {
+  const pfx = prefix || '';
+  const el = document.getElementById(pfx ? 'cp-status-desktop' : 'cp-status');
+  const btn = document.getElementById(pfx ? 'cp-start-desktop' : 'cp-start');
+  try {
+    if (el) { el.textContent = 'проверка…'; el.className = 'tag'; }
+    const r = await fetch('/api/phone/status');
+    const d = await r.json();
+    const ok = d.running && d.adb;
+    if (el) {
+      el.textContent = ok ? '● запущен' : '○ выключен';
+      el.className = 'tag ' + (ok ? 'tag-on' : 'tag-off');
+    }
+    if (btn) btn.textContent = d.running ? '→ Закрыть' : '▶ Старт';
+    return d;
+  } catch (e) {
+    if (el) { el.textContent = '? ошибка'; el.className = 'tag tag-off'; }
+    return { running: false };
+  }
+}
+async function cloudPhoneStart(prefix) {
+  const pfx = prefix || '';
+  const d = await cloudPhoneStatus(pfx);
+  const btn = document.getElementById(pfx ? 'cp-start-desktop' : 'cp-start');
+  if (d.running && d.adb) { cloudPhoneConnect(pfx); return; }
+  if (btn) { btn.textContent = '▶ Запуск…'; btn.disabled = true; }
+  try {
+    const r = await fetch('/api/phone/start', { method: 'POST' });
+    const j = await r.json();
+    if (btn) { btn.disabled = false; btn.textContent = '▶ Старт'; }
+    if (j.ok) {
+      const poll = setInterval(async () => {
+        const s = await cloudPhoneStatus(pfx);
+        if (s.running) { clearInterval(poll); cloudPhoneConnect(pfx); }
+      }, 4000);
+    } else {
+      phoneMsg('Не удалось запустить телефон:\n' + (j.message || j.error || ''));
+    }
+  } catch (e) { phoneMsg('Ошибка запуска: ' + e.message); }
+}
+async function cloudPhoneStop(prefix) {
+  const pfx = prefix || '';
+  try {
+    await fetch('/api/phone/stop', { method: 'POST' });
+    const frame = document.getElementById(pfx ? 'cp-frame-desktop' : 'cp-frame');
