         path: p,
         name: path.basename(p),
         remote: run(['config', '--get', 'remote.origin.url']) || null,
         branch: run(['rev-parse', '--abbrev-ref', 'HEAD']) || null,
         head: run(['rev-parse', 'HEAD']) || null,
