 const attachPtyClient = (session, ws) => {
   session.clients.add(ws);
   session.lastLeave = 0;
   ws.send(JSON.stringify({ type: 'opened', id: session.id, resumed: session.resumed }));
   // Экран, переживший туннель или раннер. Живой вывод всегда важнее снимка, и
   // когда он есть (переподключение, revive после рестарта хаба) он сам несёт
   // актуальное состояние — поэтому снимок отдаём только когда показать нечего:
   // сессия восстановлена из descriptors/ и tmux только что создан заново.
   // Иначе терминал мигает чёрным, и это выглядит как «агент потерялся».
   if (!session.output) {
     const snap = readSessionSnapshot(session.id);
     if (snap) {
       ws.send(JSON.stringify({
         type: 'output', id: session.id,
         data: snap.data.replace(/\s+$/, '') + '\r\n',
         replay: true, replayEnd: false, snapshot: true, snapshotAt: snap.at
       }));
     }
   }
   if (session.tmux) {
     const hist = tmuxAttachHistory(session);
     if (hist) ws.send(JSON.stringify({ type: 'output', id: session.id, data: hist, replay: true, replayEnd: false }));
     // Перерисовка сразу (не ждать replay) и страхующая после него.
     scheduleTuiRepaint(session, 300, 1);
     const replayMs = session.output
       ? Math.ceil(Math.min(session.output.length, SESSION_REPLAY_BYTES) / SESSION_OUTPUT_CHUNK) * 10
       : 0;
     scheduleTuiRepaint(session, replayMs + 1200, 2);
   }
   // Replay the scrollback in chunks, not one multi-MB WS frame: a single
   // huge frame is buffered by mobile browsers / tunnels and the terminal
   // appears to load only a fragment before it freezes. 64KB per message with
   // a micro-break lets the client render progressively and stay responsive.
   //
   // Only the tail goes out (see SESSION_REPLAY_BYTES): the client resets the
   // terminal on the first replay frame, so anything older than the tail would
   // be replayed and then thrown away while still costing a main-thread stall.
   if (session.output) {
     const out = session.output.length > SESSION_REPLAY_BYTES
       ? session.output.slice(-SESSION_REPLAY_BYTES)
       : session.output;
     let pos = 0;
     const step = () => {
       if (ws.readyState !== 1 || pos >= out.length) return;
       const part = out.slice(pos, pos + SESSION_OUTPUT_CHUNK);
       pos += part.length;
       const last = pos >= out.length;
       ws.send(JSON.stringify({ type: 'output', id: session.id, data: part, replay: true, replayEnd: last }));
       if (!last) setTimeout(step, 10);
     };
     step();
   }
