   item.pending += data;
   // Escape hatch: a monster paste must not wait for the debounce indefinitely.
   if (item.pending.length > 16384) { tmuxInputFlush(id); return; }
   item.timer = setTimeout(() => tmuxInputFlush(id), 30);
