       case 'open': {
         const id = msg.sessionId || ('term_' + Date.now());
         const savedMeta = readSessionMeta(id);
         const existing = sessions.get(id);
         if (existing && (!existing.tmux || tmuxSessionAlive(id))) {
           session = existing;
           session.resumed = true;
           attachPtyClient(session, ws);
           tmuxWake(session);
