         const toolCmd = commandForTool(tool, savedMeta);

         try {
           if (tmuxHas() && !isWin) {

             // ❗ tmux requires a login shell name (argv[0]) to start bash as an
             // interactive shell; new-session already does that. Nothing more needed.
