       `${why ? ` reason="${why}"` : ''}` +
       ` alive=${Math.round((Date.now() - (ws.openedAt || Date.now())) / 1000)}s` +
       ` silent=${Math.round((Date.now() - (ws.lastSeen || Date.now())) / 1000)}s` +
       ` session=${(session && session.id) || '-'}`);
