   const id = m.id;
   let code = null;
   try { code = parseInt(fs.readFileSync(aiPath(id, '.done'), 'utf8').trim(), 10); } catch {}
   const alive = !!(tmuxHas() && tmuxRun(['has-session', '-t', aiSafe(id)], 2000).status === 0);
   return {
     ...m, alive, done: code !== null && !alive,
     exitCode: code, tail: aiTail(id)
   };
 };
