 function sh(cmd, timeoutMs = 60000, extraEnv) {
   return new Promise((resolve) => {
     let child;
     try {
       child = spawn('bash', ['-lc', cmd], {
         env: extraEnv ? { ...process.env, ...extraEnv } : process.env,
         stdio: ['ignore', 'pipe', 'pipe']
