/**
 * Arm the screen WITHOUT starting it.
 *
 * Two different jobs used to live in one `start()`, and the user asked for the
 * split: the npm-hub runner must not carry an X11 desktop nobody opened, while
 * the separate «Экран» page still has to work the moment it is opened.
 *
 *   arm()  — always, at hub boot. Cheap and side-effect-free on the desktop:
 *            resolves the script root, sets the gate, registers /novnc and the
 *            /ws/desktop upgrade relay. The relay MUST live here: the noVNC UI
 *            is static-served, but its websocket (`path=ws/desktop` in
 *            NOVNC_QUERY) only exists once registerProxy ran. Arming only the
 *            desktop would leave the page with a permanently broken iframe.
 *   wake() — on demand, when the «Экран» page asks. Brings the desktop up and,
 *            crucially, starts the 15 s repair tick with it.
 *
 * @param {{repoRoot:string, app:object, server:object, port:number, log?:Function}} opts
 */
function arm(opts = {}) {
  state.log = typeof opts.log === 'function' ? opts.log : (m) => console.log('  🖥 ' + m);
  if (process.platform !== 'linux') {
    state.note = 'desktop unavailable on ' + process.platform;
    return { status, localStatus, ensureNow: async () => false, wake: async () => false, repair: async () => false, registerProxy: () => {}, stop: () => {}, keepalive: state };
  }
  const has = (dir) => Boolean(dir) && fs.existsSync(path.join(dir, 'tools', 'start_desktop.sh'));
  // Prefer the checkout this very file lives in (npm-hub/src → ../.. = repo
  // root), then whatever the caller resolved (workspace/fork on Actions, the
  // work dir elsewhere). Without this a hub started by hand would look for the
  // desktop script in ~/hub-work and silently skip the always-on screen.
  const own = path.resolve(__dirname, '..', '..');
  const root = has(own) ? own : (has(opts.repoRoot) ? opts.repoRoot : null);
  if (!root) {
    state.note = 'start_desktop.sh не найден (искал в ' + own + ' и ' + (opts.repoRoot || '?') + ')';
    state.log('экран недоступен: ' + state.note);
    return { status, localStatus, ensureNow: async () => false, wake: async () => false, repair: async () => false, registerProxy: () => {}, stop: () => {}, keepalive: state };
  }
  repoRootRef = root;
  state.enabled = true;
  // Still "starting" as far as the panel is concerned: localStatus() reports
  // `pending` while the X display is down, which is what keeps the panel from
  // showing another runner's screen while ours is asleep. Waking is a separate
  // step, so the note says so instead of promising a desktop that is not up.
  state.note = 'armed (спит до вкладки «Экран»)';
  // Before registerProxy: the proxy's upgrade handler reads state.gate.
  state.gate = typeof opts.gate === 'function' ? opts.gate : null;
  if (opts.app && opts.server) {
    try { registerProxy(opts.app, opts.server); } catch (e) { state.note = 'proxy: ' + e.message; }
  }
  return keeper();
}

// Idempotent: many page loads and many status polls may ask at once, and the
// repair tick must exist as soon as the desktop does - a desktop nobody repairs
// is the exact failure this keepalive was written for.
async function wake(why) {
  if (!state.enabled || !repoRootRef) return false;
  if (state.busy) return true;          // уже поднимается/чинится
  if (state.desktop === 'yes' && state.woke && keeperTimer) return true;
  state.busy = true;
  state.woke = true;
  state.note = 'starting';
  try {
    const w = await which('x11vnc');
    if (!w) state.log('ставлю desktop-стек (первый раз, ~1 мин)…');
    const ok = await fullStart(repoRootRef);
    if (ok) {
      state.note = 'running';
      // Prove the pixels are really there: the top-left 40x40 must not be a
      // single flat colour (that is exactly the black screen the user saw).
      const shot = await sh(`DISPLAY=${DISPLAY} import -window root -crop 40x40+0+0 txt:- 2>/dev/null | tail -n +2 | awk '{print $3}' | sort -u | wc -l`, 20000);
      const colors = parseInt(shot.out, 10);
      state.paint = colors > 1 ? 'ok' : 'flat';
      state.note = colors > 1 ? 'running (paint ok)' : 'running (paint flat?)';
    }
    // Repair tick starts WITH the desktop, not with the hub. Before the split
    // this interval was created in start(); left there it would have polled a
    // sleeping desktop and the first wake would come with nobody repairing it.
    if (!keeperTimer) {
      keeperTimer = setInterval(() => { tick().catch(() => {}); }, TICK_MS);
      setTimeout(() => { tick().catch(() => {}); }, 5000);
    }
    return ok;
  } finally {
    state.busy = false;
  }
}

let keeperTimer = null;

function keeper() {
  return {
    status,
    localStatus,
    // Both the manual «починить» and the page's wake-up go through wake(), so
    // the repair tick always comes along. ensureNow used to be a bare
    // fullStart(): the desktop came up and nothing ever fixed it afterwards.
    ensureNow: (why) => wake(why || 'api/ensure'),
    wake,
    repair: (why) => repair(repoRootRef, why || 'manual'),
    tick,
    size: () => desktopSize(),
    registerProxy,
    stop: () => { if (keeperTimer) { clearInterval(keeperTimer); keeperTimer = null; } },
    keepalive: state
  };
}

