input.newString:
// ─── ALWAYS-ON DESKTOP ───
// The screen belongs to the OTHER runner, not to npm-hub, so the hub must not
// boot it: arm() at hub start only registers the proxy routes (/novnc +
// /ws/desktop) and the gate, and the separate «Экран» page calls the keeper to
// wake the Xvfb/openbox/x11vnc stack when it is actually opened. Started
// before the listener so the proxy is registered on `server`.
let vncKeeper = null;
try {
  vncKeeper = require('./vnc-keepalive').arm({
    repoRoot: GIT_ROOT,
    app,
    server,
    port: PORT,
    gate: (req, socket) => gateDenySocket(req, socket),
    log: (m) => console.log('  🖥 ' + m)
  });
  console.log('  🖥 Screen armed: ' + JSON.stringify(vncKeeper.status().note)
    + ' (спит до вкладки «Экран»)');
} catch (e) {
  console.log('  🖥 vnc-keepalive не поднялся: ' + e.message);
}

