input.newString:
app.post('/api/vnc/keepalive', async (req, res) => {
  if (!vncKeeper) return res.json({ ok: false, error: 'keepalive не подключён' });
  const action = (req.body && req.body.action) || 'repair';
  try {
    // 'ensure' is what the separate «Экран» page sends on load: wake the
    // desktop. It goes through the keeper's wake(), so the 15 s repair tick is
    // created together with the desktop - the screen must not come up
    // unattended, that is the failure this keepalive exists to prevent.
    if (action === 'ensure' || action === 'wake') {
      const done = await vncKeeper.ensureNow('страница «Экран»');
      res.json({ ok: true, action, done, status: vncKeeper.status() });
      return;
    }
    const ok = action === 'rebuild' ? await vncKeeper.ensureNow('панель: rebuild') : await vncKeeper.repair('запрос панели');
    res.json({ ok: true, action, done: ok, status: vncKeeper.status() });
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});

