s = open('/tmp/opencode/moved-block.js', encoding='utf-8').read()

# 1) linuxOpen(): на отдельной странице «Экран» уже всё, разворачиваем сразу.
old_open = """function linuxOpen() {
  showPage('linux');
  let skip = false; try { skip = sessionStorage.getItem('hub_nofs') === '1'; } catch {}
  const touchy = (navigator.maxTouchPoints || 0) > 0 && Math.min(screen.width, screen.height) < 820;
  if (skip || !touchy) return;
  setTimeout(() => { try { linuxFullscreen(true); } catch {} }, 400);
}"""
new_open = """function linuxOpen() {
  // Отдельная страница: переключать нечего, она уже открыта. На телефоне
  // сразу разворачиваем стол (и в ландшафт) — иначе видно мелкую картинку.
  let skip = false; try { skip = sessionStorage.getItem('hub_nofs') === '1'; } catch {}
  const touchy = (navigator.maxTouchPoints || 0) > 0 && Math.min(screen.width, screen.height) < 820;
  if (skip || !touchy) return;
  setTimeout(() => { try { linuxFullscreen(true); } catch {} }, 400);
}"""
assert old_open in s
s = s.replace(old_open, new_open)

# 2) hubBrowserGo / browserOpenDesktop: на этой странице экран УЖЕ открыт.
s = s.replace("""  linuxRunBrowser(url, isYt);
  fmInfo('🌐 ' + url + ' → открываю на экране (звук вкл)');
  showPage('linux');
}""", """  linuxRunBrowser(url, isYt);
  screenNote('🌐 ' + url + ' → открываю на экране (звук вкл)');
}""")
s = s.replace("""  linuxRunBrowser(url, vertical);
  fmInfo((vertical?'📱 Вертикальный браузер: ':'🖥 Браузер: ')+url+' → смотри в «Экран» (звук вкл)');
  showPage('linux');
  setTimeout(()=>{ linuxConnect(); }, 900);
}""", """  linuxRunBrowser(url, vertical);
  screenNote((vertical?'📱 Вертикальный браузер: ':'🖥 Браузер: ')+url+' (звук вкл)');
  setTimeout(()=>{ linuxConnect(); }, 900);
}""")
assert "showPage('linux')" not in s, [l for l in s.split('\n') if "showPage('linux')" in l]

# 3) openInHubBrowser на странице экрана = обычная отправка ссылки на стол.
s = s.replace("window.openInHubBrowser = (url)=>{ browserAgentHint(url); hubBrowserGo(url); };",
              "window.openInHubBrowser = (url)=>{ browserAgentHint(url); hubBrowserGo(url); };\n"
              "// Ссылка из агента или из хаба приходит сюда и сразу уходит на стол.")

open('/tmp/opencode/moved-block.js','w',encoding='utf-8').write(s)
print('ok')
PY

input.command:
cd npm-hub/public && cat > /tmp/opencode/screen-head.js <<'HEAD'
/* =========================================================================
 * screen-app.js — страница «Экран» и её настройки (/linux).
 *
 * Экран и Настройки уехали сюда из хаба (npm-hub/public/mobile.html и
 * desktop.html) по требованию владельца: рабочий стол — это ДРУГОЙ раннер,
 * и npm-hub не должен поднимать его вместе с собой. Поэтому:
 *
 *   * в hub.yml остаётся только proxy-регистрация (/novnc + /ws/desktop),
 *     а Xvfb/openbox/x11vnc поднимаются по первому открытию этой страницы
 *     (POST /api/vnc/keepalive {action:'ensure'} в pageInit ниже);
 *   * сюда переехало всё, что управляет экраном: автоподключение, полный
 *     экран, зум/плавность, виртуальная мышь, звук видео, AVD, TTS/OCR;
 *   * хаб сюда только ПЕРЕХОДИТ (/linux) и может передать ссылку, которую
 *     надо открыть на столе (sessionStorage screen.pending_url).
 *
 * Код ниже переехал из mobile-app.js как есть; переписано ровно три вещи,
 * которые на отдельной странице не имеют смысла: linuxOpen() больше не
 * переключает вкладку, hubBrowserGo()/browserOpenDesktop() не уходят
 * «в Экран» (он уже открыт), а fmInfo заменён на screenNote — хабового
 * тоста на этой странице нет.
 * ========================================================================= */

// Тоста хаба здесь нет: страница отдельная, а fmInfo жил в mobile-app.js.
// Пишем в ту же строку под панелью — пользователю нужно видеть, куда ушла
// ссылка и что экран поднимается.
function screenNote(text) {
  const el = document.getElementById('linux-note');
  if (el) { el.textContent = text; el.title = text; return; }
  try { console.log('  🖥 ' + text); } catch {}
}

// Будим десктоп. Раньше он поднимался при старте хаба (vnc-keepalive.start),
// теперь хаб только «взводит» маршруты, а стек экрана — здесь. Первый запуск
// ставит desktop-стек (~минута), дальше это секунды; статус и плейсхолдер
// показывают происходящее, поэтому ответ можно не ждать.
async function screenWake() {
  try {
    const r = await fetch('/api/vnc/keepalive', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: 'ensure' })
    });
    const d = await r.json().catch(() => null);
    if (d && d.ok === false) screenNote('экран: ' + (d.error || 'не поднялся'));
  } catch (e) {
    try { screenNote('экран: хаб не отвечает — ' + (e && e.message || e)); } catch {}
  }
}

// Ссылка, оставленная хабом (Files → «Открыть на экране», Git → 🌐, агент).
// Открываем один раз и только когда экран реально готов: пока стек ставится,
// /api/linux/run отвечает «pending», и окно потерялось бы.
let pendingUrlChecked = false;
function screenTakePendingUrl() {
  if (pendingUrlChecked) return null;
  pendingUrlChecked = true;
  let url = '';
  try { url = sessionStorage.getItem('screen.pending_url') || ''; } catch {}
  if (!url) return null;
  let vertical = false;
  try { vertical = sessionStorage.getItem('screen.pending_vertical') === '1'; } catch {}
  try {
    sessionStorage.removeItem('screen.pending_url');
    sessionStorage.removeItem('screen.pending_vertical');
  } catch {}
  return { url, vertical };
}

let pendingUrl = null;

function pageInit() {
  screenWake();
  pendingUrl = screenTakePendingUrl();
  // На телефоне стол сразу на весь экран — иначе мелкая картинка в рамке.
  try { linuxOpen(); } catch {}
  if (pendingUrl) {
    const u = pendingUrl;
    pendingUrl = null;
    // Ждём готовности: linuxConnect() дёргает нас при появлении кадра.
    screenPendingOpen = u;
    screenNote('🖥 ' + u + ' → открою, как только экран поднимется');
  }
}
let screenPendingOpen = null;

HEAD
cat /tmp/opencode/screen-head.js /tmp/opencode/moved-block.js > screen-app.js && node --check screen-app.js && echo SCREEN_OK && wc -l screen-app.js

