from html.parser import HTMLParser
VOID={'br','img','input','link','meta','hr','iframe','source','area','base','col','embed','param','track','wbr'}
class P(HTMLParser):
    def __init__(self):
        super().__init__(); self.stack=[]; self.err=[]
    def handle_starttag(self, tag, attrs):
        if tag in VOID: return
        self.stack.append(tag)
    def handle_endtag(self, tag):
        if not self.stack: self.err.append('extra </%s>'%tag); return
        if self.stack[-1]!=tag:
            self.err.append('mismatch: open <%s> vs close </%s>'%(self.stack[-1],tag))
        self.stack.pop()
for f in ('linux.html','mobile.html'):
    p=P(); p.feed(open(f,encoding='utf-8').read())
    print(f, '| errors:', p.err[:4], '| unclosed:', p.stack)
