cd npm-hub/public && python3 - <<'PY'
import re
s = open('desktop-app.js', encoding='utf-8').read().split('\n')
assert s[2561].startswith('// ===== CLOUD PHONE'), s[2561]
assert s[3560].strip() == '' and s[3560+1].startswith('// ===== GITHUB REPO BROWSER'), s[3561]
rm = set(range(2562, 3560))   # 2562..3559 — экран, облачный телефон, TTS/OCR, мышь, звук
out = [l for i, l in enumerate(s, 1) if i not in rm]
t = '\n'.join(out)

# 1) Статус профиля Chrome — часть экрана, на хабе ему нечего показывать.
t = t.replace("  renderDashboard(); renderSidebar();\n  setTimeout(() => { initFM(); fmBrowse(workDir || homeDir); }, 300);\n  chromeProfileStatus();\n",
              "  renderDashboard(); renderSidebar();\n  setTimeout(() => { initFM(); fmBrowse(workDir || homeDir); }, 300);\n")

# 2) Экрана на хабе больше нет — вкладки 'linux' не существует.
t = t.replace("  if (p === 'git') loadGit();\n  if (p === 'linux') linuxAutoConnect();\n",
              "  if (p === 'git') loadGit();\n")

# 3) Облачный телефон жил на странице экрана.
t = t.replace("showPage('files');\n// восстанавливаем адрес облачного телефона и держим его актуальным\n(function(){ try { cpRestoreLastUrl(); } catch {} })();\n",
              "showPage('files');\n")

# 4) «Открыть на экране» из Файлов — уход на отдельную страницу /linux.
old = """  linuxRunBrowser(url);
  showPage('linux');
  setTimeout(() => linuxConnect(), 800);
}"""
new = """  screenGo(url, false);
}"""
assert old in t
t = t.replace(old, new)

# 5) Ссылка с хаба на экран: тот же переход, что и в mobile-app.js.
anchor = "async function fmOpenScreen() {"
block = """// ===== ЭКРАН ЖИВЁТ НА ОТДЕЛЬНОЙ СТРАНИЦЕ (/linux) =====
// Экран и его настройки уехали из хаба: рабочий стол — это другой раннер, и
// npm-hub не должен поднимать его вместе с собой. С хаба остаётся переход:
// оставляем ссылку в sessionStorage и уходим на /linux, страница откроет её,
// когда стол будет готов.
function screenGo(url, vertical) {
  if (!url) return;
  url = url.trim();
  if (!/^https?:\\/\\//i.test(url) && !/^\\//.test(url)) url = 'https://' + url;
  try {
    sessionStorage.setItem('screen.pending_url', url);
    sessionStorage.setItem('screen.pending_vertical', vertical ? '1' : '0');
  } catch {}
  location.href = '/linux';
}
function browserOpenDesktop(url, vertical) {
  if (!url) return;
  url = url.trim(); if (!/^https?:\\/\\//i.test(url)) url = 'https://' + url;
  screenGo(url, vertical === true);
}
function hubBrowserGo(url) {
  if (!url) return;
  url = url.trim();
  if (!/^https?:\\/\\//i.test(url)) url = 'https://' + url;
  try { localStorage.setItem('hub_browser_last', url); } catch {}
  screenGo(url, /youtube|youtu\\.be/i.test(url));
}
window.openInHubBrowser = (url) => screenGo(url, false);

"""
assert anchor in t
t = t.replace(anchor, block + anchor, 1)
open('desktop-app.js','w',encoding='utf-8').write(t)
print('desktop-app.js patched')
PY
node --check desktop-app.js && echo DESK_OK && wc -l desktop-app.js

